"""Module pdfsyntax.objects: core PDF syntax parsing and manipulation"""

import zlib

def serialize(obj):
    """ Serialize Python object to PDF syntax byte string """
    if isinstance(obj, dict):
        items = []
        for k, v in obj.items():
            items.append(serialize(k))
            items.append(serialize(v))
        return b'<< ' + b' '.join(items) + b' >>'
    elif isinstance(obj, list):
        items = [serialize(item) for item in obj]
        return b'[ ' + b' '.join(items) + b' ]'
    elif isinstance(obj, bool):
        return b'true' if obj else b'false'
    elif isinstance(obj, int) or isinstance(obj, float):
        return str(obj).encode('ascii')
    elif isinstance(obj, str):
        # Handle string serialization (for names and literals)
        if obj.startswith('/'):
            return obj.encode('ascii')
        else:
            # For literal strings, we need to encode them properly
            return b'(' + obj.encode('utf-8') + b')'
    elif isinstance(obj, bytes):
        return obj
    else:
        # Default to string representation
        return str(obj).encode('ascii')


def next_token(text, i=0):
    """ syntax Find next token in raw string starting at some index
    """
    search = "TBD"
    nested = 1
    h = i
    while i < len(text):
        single = text[i:i+1]
        double = text[i:i+2]
        if search == "TBD":
            if double == b'<<':
                search = "DICT"
            elif single == b'[':
                search = "ARRAY"
            elif single == b'/':
                search = "NAME"
            elif text[i:i+6] == b"stream":
                search = "STREAM"
                offset = 7 if text[i+6:i+7] == b'\n' else 8 # else is b'\r\n'
                i += offset
            elif single in b"+-.0123456789":
                search = "VALUE"
            elif single in b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ":
                search = "KEYWORD"
            elif single in b"(<":
                search = "TEXT"
            elif single == b't':
                # Check for true/false keywords
                if text[i:i+4] == b'true':
                    return (i, i+4, 'TRUE')
                elif text[i:i+5] == b'false':
                    return (i, i+5, 'FALSE')
            elif single == b'%':
                # Skip comment - find the actual start of the comment (skip leading whitespace)
                # Set h to the position of the % character
                h = i
                while i < len(text) and text[i:i+1] not in b'\r\n':
                    i += 1
                while i < len(text) and text[i:i+1] in b'\r\n':
                    i += 1
                return (h, i, 'COMMENT')
            h = i
        elif search == "DICT":
            if double == b'<<':
                nested += 1
                i += 1
            elif double == b'>>':
                nested -= 1
                i += 1
            if nested == 0:
                return (h, i + 1, 'DICT')
        elif search == "NAME":
            if single in b' \n\r[]/<>(' or i >= len(text):
                return (h, i, 'NAME')
            i += 1
            continue
        elif search == "TEXT":
            if double == b'\\(' or double == b'\\)' or double == b'\\<' or double == b'\\>':
                i += 1
            elif single == b'(':
                # Handle opening parenthesis in literal strings
                paren_count = 1
                i += 1
                while i < len(text) and paren_count > 0:
                    if text[i:i+1] == b'(':
                        paren_count += 1
                    elif text[i:i+1] == b')':
                        paren_count -= 1
                    i += 1
                return (h, i, 'STRING')
            elif single == b'<':
                # Handle hexadecimal strings
                i += 1
                while i < len(text) and text[i:i+1] not in b'>':
                    i += 1
                if i < len(text) and text[i:i+1] == b'>':
                    i += 1
                return (h, i, 'STRING')
            elif single in b')>':
                return (h, i + 1, 'STRING')
            i += 1
            continue
        elif search == "KEYWORD":
            if single in b' \n\r>/]' or i >= len(text) or i == len(text) - 1:
                # Check if it's a special keyword
                keyword = text[h:i]
                if keyword == b'true':
                    return (h, i, 'TRUE')
                elif keyword == b'false':
                    return (h, i, 'FALSE')
                return (h, i, 'KEYWORD')
        elif search == "VALUE":
            # Check if we've reached the end of the string
            if i >= len(text):
                # We've reached the end of the string - return appropriate token type
                # Determine if it's integer or real
                if b'.' in text[h:i] or b'e' in text[h:i].lower():
                    return (h, i, 'REAL')
                else:
                    return (h, i, 'INTEGER')
            # If we're at the last character, we need to check if it's a valid terminator
            if i == len(text) - 1:
                # We're at the last character of the string, and it's a value character
                # This means the token is incomplete - but we still need to return the type
                # Determine if it's integer or real
                if b'.' in text[h:i] or b'e' in text[h:i].lower():
                    return (h, i + 1, 'REAL')
                else:
                    return (h, i + 1, 'INTEGER')
            if single in b' \n\r>/]':
                # Determine if it's integer or real
                if b'.' in text[h:i] or b'e' in text[h:i].lower():
                    return (h, i, 'REAL')
                else:
                    return (h, i, 'INTEGER')
            i += 1
            continue
        elif search == "STREAM":
            if text[i:i+11] == b'\r\nendstream' or text[i:i+10] == b'\nendstream':
                return (h, i, 'STREAM')
        elif search == "ARRAY":
            if single == b'[':
                nested += 1
            elif single == b']':
                nested -= 1
            if nested == 0:
                return (h, i + 1, 'ARRAY')
        i += 1

    # Handle incomplete tokens at end of string
    # For incomplete tokens, we return (start_index, end_index, token_type)
    # Check if we have a partial token that would be incomplete
    if search == "NAME":
        return (h, i, 'NAME')
    elif search == "VALUE":
        # Return incomplete VALUE token with appropriate type
        if i > h:
            # Determine if it's integer or real
            if b'.' in text[h:i] or b'e' in text[h:i].lower():
                return (h, i, 'REAL')
            else:
                return (h, i, 'INTEGER')
        else:
            return (h, i, None)
    elif search == "TEXT":
        # Incomplete TEXT token - treat as STRING
        return (h, i, 'STRING')
    elif search == "DICT":
        # Incomplete DICT token - treat as DICT
        return (h, i, 'DICT')
    elif search == "ARRAY":
        # Incomplete ARRAY token - treat as ARRAY
        return (h, i, 'ARRAY')

    # For all other cases, return None for the token type (incomplete)
    return (h, i, None)


def replace_ref(tokens):
    """ syntax
    """
    size = len(tokens)
    new_list = []
    i = 0
    while i < size:
        # Check if we have a potential reference: number 0 R
        # Since tokens are raw bytes, we need to check for bytes objects
        if (i < size - 2 and 
            isinstance(tokens[i], (bytes, str)) and 
            tokens[i+1] == b'0' and 
            tokens[i+2] == b'R'):
            # Create a complex number representation for reference (as done in original)
            # This follows the convention that 6 0 R becomes 6j
            try:
                ref_num = int(tokens[i])
                new_list.append(complex(0, ref_num))
                i += 3
            except (ValueError, TypeError):
                # If conversion fails, treat as regular token
                new_list.append(tokens[i])
                i += 1
        elif (i < size - 1 and 
              isinstance(tokens[i], (bytes, str)) and 
              tokens[i+1] == b'R' and 
              isinstance(tokens[i-1], (bytes, str)) and 
              tokens[i-1] == b'0'):
            # This is the '0 R' part of a reference, skip it as it was already processed
            i += 2
        else:
            new_list.append(tokens[i])
            i += 1
    return new_list


def decode_predictor(bdata, predictor, columns):
    size = len(bdata)
    res = b''
    columns += 1
    prev_row = [0] * columns
    i = 0
    while i < size:
        row = list(bdata[i:i+columns])
        decoded_row = [(val + prev_row[index]) & 0xff for (index, val) in enumerate(row)]
        prev_row = decoded_row
        res += bytes(decoded_row[1:])
        i += columns
    return res


def decode_stream(stream, stream_def):
