def parse_obj(text, start=0):
    """ syntax
    """
    # Skip leading whitespace and comments
    i = start
    while i < len(text):
        # Skip whitespace
        while i < len(text) and text[i:i+1] in b' \n\r\t':
            i += 1

        # Skip comments
        if i < len(text) and text[i:i+1] == b'%':
            while i < len(text) and text[i:i+1] not in b'\r\n':
                i += 1
            while i < len(text) and text[i:i+1] in b'\r\n':
                i += 1
            continue

        break

    if i >= len(text):
        return None

